<?php
declare(strict_types=1);
define('HWC_SKIP_GLOBAL_SHELL',true);
require_once __DIR__.'/config/dynamic_forms.php';
try{$pdo=role_portal_db();dynamic_forms_ensure($pdo);}catch(Throwable $e){http_response_code(503);?><!doctype html><html><head><meta name="viewport" content="width=device-width"><style>body{display:grid;place-items:center;min-height:100vh;font-family:Arial;background:#f7f8fd}.card{padding:28px;border-radius:18px;background:#fff;box-shadow:0 15px 45px #ccd}button{padding:10px;background:#5844da;color:#fff;border:0;border-radius:9px}</style></head><body><div class="card"><h2>Database is not running</h2><p>Start MySQL and Apache in XAMPP. No data was changed.</p><button onclick="location.reload()">Retry Connection</button></div></body></html><?php exit;}
security_step17_session_start();$user=security_step17_session_user($pdo,true);
if(!$user){header('Location: ../login.php');exit;}
if((string)$user['role_code']!=='admin'){header('Location: access_denied.php');exit;}
if((string)($_GET['create']??'')==='1'){header('Location: custom_form_create.php');exit;}
$ctx=security_step17_context($pdo);$orgId=(int)$ctx['organization_id'];$csrf=security_step17_csrf();$error=$success=null;
try{if($_SERVER['REQUEST_METHOD']==='POST'){security_step17_verify_csrf((string)($_POST['csrf']??''));$action=(string)($_POST['action']??'');
if($action==='save_form'){$name=trim((string)($_POST['form_name']??''));$key=preg_replace('/[^a-z0-9_]+/','_',strtolower(trim((string)($_POST['form_key']??''))));$key=trim((string)$key,'_');if($name===''||$key==='')throw new RuntimeException('Form name and unique form key are required.');$s=$pdo->prepare("INSERT INTO dynamic_form_definitions(organization_id,form_key,form_name,target_page,description,sort_order,status,is_custom,created_by,updated_by) VALUES(?,?,?,'dynamic_form_entry.php',?,?,'active',1,?,?)");$s->execute([$orgId,$key,$name,trim((string)($_POST['description']??'')),(int)($_POST['sort_order']??100),(int)$user['id'],(int)$user['id']]);$_POST['selected_form']=$key;$success='New custom form created. Add its fields below.';}
if($action==='save_field'){$formId=(int)($_POST['form_id']??0);$fieldId=(int)($_POST['field_id']??0);$key=trim((string)($_POST['field_key']??''));$label=trim((string)($_POST['field_label']??''));if(!$formId||$key===''||$label==='')throw new RuntimeException('Form, field name and label are required.');$type=in_array((string)($_POST['field_type']??''),['select','radio','checkbox','text'],true)?(string)$_POST['field_type']:'select';$status=in_array((string)($_POST['status']??''),['active','hidden'],true)?(string)$_POST['status']:'active';$parent=(int)($_POST['parent_field_id']??0)?:null;if($parent===$fieldId)$parent=null;$v=[$key,$label,$type,trim((string)($_POST['help_text']??'')),$parent,isset($_POST['is_required'])?1:0,(int)($_POST['sort_order']??100),$status];if($fieldId){$s=$pdo->prepare('UPDATE dynamic_form_fields SET field_key=?,field_label=?,field_type=?,help_text=?,parent_field_id=?,is_required=?,sort_order=?,status=? WHERE id=? AND organization_id=?');$s->execute([...$v,$fieldId,$orgId]);}else{$s=$pdo->prepare('INSERT INTO dynamic_form_fields(organization_id,form_id,field_key,field_label,field_type,help_text,parent_field_id,is_required,sort_order,status) VALUES(?,?,?,?,?,?,?,?,?,?)');$s->execute([$orgId,$formId,...$v]);}$success=$fieldId?'Field updated.':'Field added.';}
elseif($action==='save_option'){$fieldId=(int)($_POST['field_id']??0);$optionId=(int)($_POST['option_id']??0);$value=trim((string)($_POST['option_value']??''));$label=trim((string)($_POST['option_label']??''));if(!$fieldId||$value===''||$label==='')throw new RuntimeException('Option label and value are required.');$parent=trim((string)($_POST['parent_option_value']??''))?:null;$status=in_array((string)($_POST['status']??''),['active','hidden'],true)?(string)$_POST['status']:'active';$v=[$value,$label,$parent,(int)($_POST['sort_order']??100),$status];if($optionId){$s=$pdo->prepare('UPDATE dynamic_form_options SET option_value=?,option_label=?,parent_option_value=?,sort_order=?,status=? WHERE id=? AND organization_id=?');$s->execute([...$v,$optionId,$orgId]);}else{$s=$pdo->prepare('INSERT INTO dynamic_form_options(organization_id,field_id,option_value,option_label,parent_option_value,sort_order,status) VALUES(?,?,?,?,?,?,?)');$s->execute([$orgId,$fieldId,...$v]);}$success=$optionId?'Option updated.':'Option added.';}
security_step17_audit($pdo,(int)$user['id'],'dynamic_form_designer_updated','dynamic_form',null,['action'=>$action]);}}catch(Throwable $e){$error=$e->getMessage();}
$forms=dynamic_forms_catalog($pdo,$orgId);$selectedKey=(string)($_GET['form']??$_POST['selected_form']??($forms[0]['form_key']??''));$selected=null;foreach($forms as $f)if((string)$f['form_key']===$selectedKey)$selected=$f;if(!$selected&&$forms)$selected=$forms[0];$fields=$options=[];if($selected){$s=$pdo->prepare('SELECT * FROM dynamic_form_fields WHERE organization_id=? AND form_id=? ORDER BY sort_order,id');$s->execute([$orgId,(int)$selected['id']]);$fields=$s->fetchAll();if($fields){$ids=array_column($fields,'id');$marks=implode(',',array_fill(0,count($ids),'?'));$s=$pdo->prepare("SELECT * FROM dynamic_form_options WHERE organization_id=? AND field_id IN ($marks) ORDER BY field_id,sort_order,id");$s->execute([$orgId,...$ids]);$options=$s->fetchAll();}}$h=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$types=['select'=>'Dropdown','radio'=>'Radio','checkbox'=>'Checkbox','text'=>'Text'];
function fieldForm(array $field,array $fields,array $selected,array $types,string $csrf,Closure $h):void{?><form method="post" class="grid"><input type="hidden" name="csrf" value="<?=$h($csrf)?>"><input type="hidden" name="action" value="save_field"><input type="hidden" name="form_id" value="<?=(int)$selected['id']?>"><input type="hidden" name="field_id" value="<?=(int)$field['id']?>"><input type="hidden" name="selected_form" value="<?=$h($selected['form_key'])?>"><label>Field Name<input name="field_key" value="<?=$h($field['field_key'])?>" required></label><label>Display Label<input name="field_label" value="<?=$h($field['field_label'])?>" required></label><label>Field Type<select name="field_type"><?php foreach($types as $v=>$l):?><option value="<?=$v?>" <?=$field['field_type']===$v?'selected':''?>><?=$l?></option><?php endforeach?></select></label><label>Depends On<select name="parent_field_id"><option value="">Independent</option><?php foreach($fields as $p):if((int)$p['id']===(int)$field['id'])continue;?><option value="<?=(int)$p['id']?>" <?=(int)$field['parent_field_id']===(int)$p['id']?'selected':''?>><?=$h($p['field_label'])?></option><?php endforeach?></select></label><label class="wide">Help Text<input name="help_text" value="<?=$h($field['help_text'])?>"></label><label>Order<input type="number" name="sort_order" value="<?=(int)$field['sort_order']?>"></label><label>Status<select name="status"><option value="active" <?=$field['status']==='active'?'selected':''?>>Active</option><option value="hidden" <?=$field['status']==='hidden'?'selected':''?>>Hidden</option></select></label><label>Required<input type="checkbox" name="is_required" value="1" <?=$field['is_required']?'checked':''?>></label><button><?=$field['id']?'Save Field Changes':'Add Field'?></button></form><?php }
function optionForm(array $o,array $field,array $selected,string $csrf,Closure $h):void{?><form method="post" class="grid option"><input type="hidden" name="csrf" value="<?=$h($csrf)?>"><input type="hidden" name="action" value="save_option"><input type="hidden" name="field_id" value="<?=(int)$field['id']?>"><input type="hidden" name="option_id" value="<?=(int)$o['id']?>"><input type="hidden" name="selected_form" value="<?=$h($selected['form_key'])?>"><label>Option Label<input name="option_label" value="<?=$h($o['option_label'])?>" required></label><label>Saved Value<input name="option_value" value="<?=$h($o['option_value'])?>" required></label><label>Parent Value<input name="parent_option_value" value="<?=$h($o['parent_option_value'])?>"></label><label>Order<input type="number" name="sort_order" value="<?=(int)$o['sort_order']?>"></label><label>Status<select name="status"><option value="active" <?=$o['status']==='active'?'selected':''?>>Active</option><option value="hidden" <?=$o['status']==='hidden'?'selected':''?>>Hidden</option></select></label><button><?=$o['id']?'Save Option Changes':'Add Option'?></button></form><?php }
?><!doctype html><html lang="en-IN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Smart Form Designer</title><style>*{box-sizing:border-box}body{margin:0;background:#f7f8fd;color:#253a30;font-family:Inter,Arial}.head{position:sticky;top:0;z-index:5;padding:16px 18px;background:linear-gradient(135deg,#fff,#eff7ff);border-bottom:1px solid #dfe7e2}.head h1{margin:0;font-size:1.25rem}.head p,.card>p{margin:4px 0;color:#6d7b74;font-size:.76rem}.tabs{display:flex;gap:7px;overflow:auto;padding:12px 16px}.tabs a{white-space:nowrap;padding:8px 11px;border:1px solid #dbe4df;border-radius:10px;background:#fff;color:#3e5148;text-decoration:none;font-size:.7rem;font-weight:800}.tabs a.active{background:#5946dc;color:#fff}.main{padding:0 16px 24px}.card{margin-bottom:12px;padding:15px;border:1px solid #dce6e0;border-radius:16px;background:#fff}.card h2{margin:0 0 4px;font-size:1rem}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px;margin-top:12px}.grid label{display:grid;gap:4px;font-size:.66rem;font-weight:800}.wide{grid-column:1/-1}input,select{width:100%;padding:9px;border:1px solid #d9e3dd;border-radius:9px;background:#fff}input[type=checkbox]{width:auto}button{padding:9px 12px;border:0;border-radius:9px;background:#247649;color:#fff;font-weight:850}.editor{margin-top:10px;padding:12px;border:1px solid #e1e5f2;border-radius:13px;background:#f9f9ff}.editor summary{cursor:pointer;color:#5140cf;font-size:.73rem;font-weight:850}.editor h3{margin:16px 0 0;font-size:.78rem}.option{padding-top:10px;border-top:1px solid #e5e8f2}.ok,.bad{margin:10px 16px;padding:10px;border-radius:10px}.ok{background:#e9f8ef;color:#176d43}.bad{background:#fff0f0;color:#a13a3a}@media(max-width:700px){.grid{grid-template-columns:1fr}.wide{grid-column:auto}}</style></head><body><header class="head"><h1>Smart Form Designer</h1><p>Administrator only • Edit existing fields and options.</p></header><?php if($success):?><div class="ok"><?=$h($success)?></div><?php endif?><?php if($error):?><div class="bad"><?=$h($error)?></div><?php endif?><nav class="tabs"><?php foreach($forms as $f):?><a class="<?=($selected&&(int)$f['id']===(int)$selected['id'])?'active':''?>" href="?form=<?=$h($f['form_key'])?>"><?=$h($f['form_name'])?></a><?php endforeach?></nav><main class="main"><?php if($selected):?><section class="card"><h2><?=$h($selected['form_name'])?></h2><p><?=$h($selected['description'])?></p></section><section class="card"><h2>Add New Field</h2><?php fieldForm(['id'=>0,'field_key'=>'','field_label'=>'','field_type'=>'select','help_text'=>'','parent_field_id'=>0,'is_required'=>0,'sort_order'=>100,'status'=>'active'],$fields,$selected,$types,$csrf,$h);?></section><section class="card"><h2>Edit Existing Fields</h2><p>Open only the field you need.</p><?php foreach($fields as $field):?><details class="editor"><summary><?=$h($field['field_label'])?> · <?=$h($field['field_key'])?></summary><?php fieldForm($field,$fields,$selected,$types,$csrf,$h);?><h3>Edit Existing Options</h3><?php $found=false;foreach($options as $o):if((int)$o['field_id']!==(int)$field['id'])continue;$found=true;optionForm($o,$field,$selected,$csrf,$h);endforeach;if(!$found):?><p>No saved options.</p><?php endif?><h3>Add New Option</h3><?php optionForm(['id'=>0,'option_label'=>'','option_value'=>'','parent_option_value'=>'','sort_order'=>100,'status'=>'active'],$field,$selected,$csrf,$h);?></details><?php endforeach?></section><?php endif?></main></body></html>
